with exploded as (select id, plan, effective_from, currency, element from price_tiers lateral view explode(tier_limits) t as element) select date_trunc('month', effective_from) as activity_month, avg(element) filter (where plan = 'starter') as starter_avg_element, count(*) as cnt, percentile_approx(element, 0.5) as element_p50 from exploded group by 1 having percentile_approx(element, 0.5) > 0 order by starter_avg_element desc
